head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil70511";
scwin.prgIfm = null;
scwin.upd_etnAttachExcelfile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.prgIfm = $c.util.getComponent('prgIfm');
        scwin.upd_etnAttachExcelfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_etnAttachExcelfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_etnAttachExcelfile"]');
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil70511.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_EtnExcelUpload_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_EtnExcelUpload_onclick = async function(e){
    try {
        await scwin.etnExcelUpload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70511.btn_EtnExcelUpload_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70511.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_EtnExcelUpload
 * @description Etn Excel Upload 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_EtnExcelUpload = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnExcelUpload",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_EtnExcelUploadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name etnExcelUpload
 * @description etn Excel Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnExcelUpload = async function () {
    if (($c.util.getComponent('upd_etnAttachExcelfile').getValue() == null ? '' : String($c.util.getComponent('upd_etnAttachExcelfile').getValue())) === '') {
        await $c.win.alert("파일을 업로드해주세요.");
        return;
    } else {
        if (!scwin.checkFileType($c.util.getComponent('upd_etnAttachExcelfile').getValue())) {
            await $c.win.alert("엑셀파일만 업로드 해주세요.");
            return;
        }
    }
    if (await $c.win.confirm("업로드 하시겠습니까?")) {
        $c.util.getComponent("searchFile").hide();
        $c.util.getComponent("confirmBtn").hide();
        scwin.prgIfm.setStyle("display", "");
        const previewWin = (Promise.resolve($c.win.openPopup("/progress_blank_pop/progress_blank_pop.xml", { id: "progressFrm", scrollbars: true, resizable: true, width: "300", height: "50", type: "pageFramePopup" }, {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("progressFrm"); this.closed = true; } });
        $c.util.getComponent('dma_EtnExcelUploadReq').set('method', 'etnExcelUpload');
        await scwin.tx_fn_EtnExcelUpload();
    }
};

/**
 * @method
 * @name checkFileType
 * @description check File Type 처리
 * @param {*} filePath filePath
 * @returns {void}
 * @hidden N
 */
scwin.checkFileType = function (filePath) {
    const fileFormat = filePath.toLowerCase();
    if (fileFormat.indexOf(".xls") > -1) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name close_pop
 * @description close pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.close_pop = function () {
    $c.win.setPageFrameSrc(null, '/jldfil70301/jldfil70301.xml', { method: "searchList", listBzCd: "3" });
    $c.win.closePopup();
};
